"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  ShoppingBag,
  Bell,
  Heart,
  Share2,
  Star,
  ShieldCheck,
  Truck,
  RotateCcw,
} from "lucide-react";
import Gallery from "./_components/gallery";
import VideoShowcase from "./_components/video-showcase";
import { Product } from "@/data/store-data";

export default function ProductPageMaster({
  product,
  similarProducts,
}: {
  product: Product;
  similarProducts: Product[];
}) {
  const [selectedSize, setSelectedSize] = useState<string | null>(null);
  const [isFavorite, setIsFavorite] = useState(false);

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: product.name,
          text: `Check out the ${product.name} on Fashion Friday!`,
          url: window.location.href,
        });
      } catch (err) {
        console.log("Share failed", err);
      }
    }
  };

  return (
    <div className="bg-background text-foreground min-h-screen pb-32 transition-colors">
      {/* --- MAIN PRODUCT GRID --- */}
      <section className="max-w-7xl mx-auto px-4 md:px-8 pt-6 lg:pt-12">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
          {/* LEFT: Gallery */}
          <div className="lg:col-span-7">
            <Gallery images={[product.promoImage, ...product.liveImages]} />
          </div>

          {/* RIGHT: Info & Purchase */}
          <div className="lg:col-span-5 lg:sticky lg:top-24 space-y-8">
            {/* 1. Brand & Actions */}
            <div className="flex justify-between items-start">
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.3em] text-foreground-muted mb-2">
                  {product.brand} • {product.quality}
                </p>
                <h1 className="text-4xl md:text-5xl font-black uppercase italic tracking-tighter leading-[0.85]">
                  {product.name}
                </h1>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setIsFavorite(!isFavorite)}
                  className="p-3 rounded-full border border-border hover:bg-background-muted transition-all"
                >
                  <Heart
                    size={20}
                    className={
                      isFavorite ? "fill-destructive text-destructive" : ""
                    }
                  />
                </button>
                <button
                  onClick={handleShare}
                  className="p-3 rounded-full border border-border hover:bg-background-muted transition-all"
                >
                  <Share2 size={20} />
                </button>
              </div>
            </div>

            {/* 2. Pricing & Rating */}
            <div className="flex items-center justify-between py-4 border-y border-border">
              <div className="flex items-center gap-4">
                <span className="text-3xl font-black">
                  ₹{product.price.toLocaleString()}
                </span>
                {product.discount > 0 && (
                  <span className="text-[10px] font-black bg-destructive text-destructive-foreground px-2 py-1 rounded-sm uppercase italic">
                    {product.discount}% OFF
                  </span>
                )}
              </div>
              <div className="flex items-center gap-1">
                <Star size={14} className="fill-brand text-brand" />
                <span className="text-sm font-black italic">4.5</span>
                <span className="text-[10px] text-foreground-subtle font-bold ml-1 uppercase">
                  (120 Reviews)
                </span>
              </div>
            </div>

            {/* 3. Description */}
            <p className="text-sm text-foreground-muted leading-relaxed">
              {product.description}
            </p>

            {/* 4. Size Selection */}
            {product.category === "sneakers" && (
              <div className="space-y-4">
                <div className="flex justify-between items-end">
                  <label className="text-[10px] font-black uppercase tracking-widest">
                    Select Size (EU)
                  </label>
                  <button className="text-[9px] font-black uppercase underline text-foreground-subtle">
                    Size Guide
                  </button>
                </div>
                <div className="flex flex-wrap gap-2">
                  {["40", "41", "42", "43", "44", "45"].map((size) => (
                    <button
                      key={size}
                      onClick={() => setSelectedSize(size)}
                      className={`w-14 h-14 rounded-xl border-2 font-black transition-all duration-300 ${
                        selectedSize === size
                          ? "border-brand bg-brand text-brand-foreground scale-95"
                          : "border-border hover:border-foreground-muted"
                      }`}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* 5. CTA Buttons */}
            <div className="pt-4">
              {product.stock > 0 ? (
                <button className="group w-full h-16 bg-brand text-brand-foreground font-black uppercase tracking-[0.2em] rounded-[1.5rem] flex items-center justify-center gap-3 active:scale-95 transition-all">
                  <ShoppingBag
                    size={20}
                    className="group-hover:rotate-12 transition-transform"
                  />
                  Add to Cart
                </button>
              ) : (
                <button className="w-full h-16 border-2 border-destructive text-destructive font-black uppercase tracking-[0.2em] rounded-[1.5rem] flex items-center justify-center gap-3">
                  <Bell size={20} />
                  Notify Me
                </button>
              )}
              <p className="text-center text-[9px] font-bold text-foreground-subtle mt-4 uppercase tracking-widest">
                Secure checkout • Free shipping on orders above ₹10k
              </p>
            </div>

            {/* 6. Trust Cards */}
            <div className="grid grid-cols-2 gap-3 pt-4">
              {[
                {
                  icon: <Truck size={18} />,
                  label: "Fast Delivery",
                  sub: "2-4 Business Days",
                },
                {
                  icon: <RotateCcw size={18} />,
                  label: "7 Day Returns",
                  sub: "Hassle-free policy",
                },
                {
                  icon: <ShieldCheck size={18} />,
                  label: "Authentic Quality",
                  sub: `${product.quality} Grade`,
                },
                {
                  icon: <Star size={18} />,
                  label: "Top Rated",
                  sub: "Trusted by 5k+ users",
                },
              ].map((item, i) => (
                <div
                  key={i}
                  className="p-4 rounded-2xl bg-background-muted border border-border flex items-center gap-3"
                >
                  <div className="text-brand shrink-0">{item.icon}</div>
                  <div>
                    <h4 className="text-[9px] font-black uppercase leading-tight">
                      {item.label}
                    </h4>
                    <p className="text-[8px] text-foreground-subtle font-bold">
                      {item.sub}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* --- VIDEO SECTION --- */}
      <section className="max-w-5xl mx-auto px-6 py-32">
        <div className="flex flex-col items-center mb-12">
          <span className="text-[10px] font-black uppercase tracking-[0.5em] text-brand mb-2 italic">
            Vision
          </span>
          <h2 className="text-3xl font-black uppercase italic tracking-tighter">
            In Motion
          </h2>
        </div>
        <VideoShowcase videoId={product.videoUrl} />
      </section>

      {/* --- REVIEWS HIGHLIGHT --- */}
      <section className="max-w-4xl mx-auto px-6 pb-20">
        <div className="bg-background-muted p-8 md:p-12 rounded-[3rem] border border-border">
          <h3 className="text-xl font-black uppercase italic mb-8">
            Community Verdict
          </h3>
          <div className="space-y-8">
            {product.reviews.map((rev, i) => (
              <div
                key={i}
                className="flex flex-col md:flex-row gap-6 items-start pb-8 border-b border-border last:border-0"
              >
                <img
                  src={rev.userImage}
                  className="w-12 h-12 rounded-full border border-border grayscale hover:grayscale-0 transition-all"
                />
                <div className="flex-1">
                  <div className="flex gap-1 mb-2">
                    {[...Array(5)].map((_, i) => (
                      <Star
                        key={i}
                        size={10}
                        className="fill-brand text-brand"
                      />
                    ))}
                  </div>
                  <p className="text-lg font-bold italic mb-2">
                    "{rev.comment}"
                  </p>
                  <p className="text-[10px] font-black uppercase text-foreground-subtle">
                    {rev.userName} • Verified Buyer
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
}
